package com.simibubi.create.content.legacy;

import com.simibubi.create.*;
import com.simibubi.create.foundation.mixin.LegacyBeaconAccessor;
import com.simibubi.create.infrastructure.config.CRecipes;
import java.nio.file.*;
import java.util.*;
import net.fabricmc.fabric.api.gametest.v1.GameTest;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.nbt.*;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.chat.Component;
import net.minecraft.util.ProblemReporter;
import net.minecraft.world.SimpleContainer;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.*;
import net.minecraft.world.level.storage.*;
import net.minecraft.world.phys.*;

/** Proposed native registration, inventory, real ItemEntity tick and world branch tests. Runtime UNRUN. */
public final class LegacyMaterialGameTests {
 static final BlockPos SOURCE=new BlockPos(3,4,3),LIGHT=new BlockPos(4,3,3);
 static ItemStack compound(int count,int light){var stack=new ItemStack(AllItems.CHROMATIC_COMPOUND,count);if(light!=0)stack.set(AllDataComponents.CHROMATIC_COMPOUND_COLLECTING_LIGHT,light);return stack;}
 static ItemEntity source(GameTestHelper h,int count,int light){var p=Vec3.atCenterOf(h.absolutePos(SOURCE));var item=new ItemEntity(h.getLevel(),p.x,p.y,p.z,compound(count,light));item.setDeltaMovement(Vec3.ZERO);item.setNoGravity(true);h.assertTrue(h.getLevel().addFreshEntity(item),"Actual native compound source admitted");return item;}
 static List<ItemEntity> nearby(GameTestHelper h,Item item){return h.getLevel().getEntitiesOfClass(ItemEntity.class,new AABB(h.absolutePos(SOURCE)).inflate(4),entity->entity.getItem().is(item));}
 static CompoundTag save(ItemEntity item){var out=TagValueOutput.createWithContext(ProblemReporter.DISCARDING,item.registryAccess());if(!item.save(out))throw new AssertionError("Actual item native save");return out.buildResult();}
 static ItemEntity load(GameTestHelper h,CompoundTag saved){var problems=new ProblemReporter.Collector();var loaded=EntityType.loadEntityRecursive(TagValueInput.create(problems,h.getLevel().registryAccess(),saved),h.getLevel(),EntitySpawnReason.LOAD,entity->entity);h.assertTrue(problems.isEmpty()&&loaded instanceof ItemEntity,"Genuine native entity codec");return (ItemEntity)loaded;}
 @GameTest public void nativeInventoryUsesDynamicLimitsForCurrentAndDecodedCompound(GameTestHelper h){var ordinary=compound(16,0);var charged=compound(2,5);var ops=h.getLevel().registryAccess().createSerializationContext(NbtOps.INSTANCE);var decoded=ItemStack.CODEC.parse(ops,ItemStack.CODEC.encodeStart(ops,charged).getOrThrow()).getOrThrow();h.assertTrue(ordinary.getMaxStackSize()==16&&charged.getMaxStackSize()==1&&decoded.getMaxStackSize()==1,"Actual ItemStack native API overrides inherited default for newly charged and old loaded stacks");var slots=new SimpleContainer(3);h.assertTrue(slots.addItem(decoded).isEmpty()&&slots.getItem(0).getCount()==1&&slots.getItem(1).getCount()==1,"Native container insertion spreads old overstacked charged items into one per slot");var limited=new SimpleContainer(1);var remainder=limited.addItem(decoded);h.assertTrue(limited.getItem(0).getCount()==1&&remainder.getCount()==1&&ItemStack.isSameItemSameComponents(limited.getItem(0),decoded)&&ItemStack.isSameItemSameComponents(remainder,decoded),"Actual full native slot retains one charged original and returns its exact component-bearing remainder without loss");h.assertTrue(AllItems.CHROMATIC_COMPOUND.isBarVisible(charged)&&AllItems.CHROMATIC_COMPOUND.getBarWidth(charged)==7&&AllItems.CHROMATIC_COMPOUND.getBarColor(charged)==0xa09db4,"Source half-charge bar width and Ponder color");h.assertTrue(ordinary.getRarity()==Rarity.UNCOMMON&&new ItemStack(AllItems.SHADOW_STEEL).getRarity()==Rarity.UNCOMMON&&new ItemStack(AllItems.REFINED_RADIANCE).hasFoil(),"Source uncommon registrations and actual native Radiance foil");h.succeed();}
 @GameTest public void actualShadowTickAppliesCreationImpulseOnceAndPersistsNativeFlags(GameTestHelper h){var source=source(h,1,0);source.setItem(new ItemStack(AllItems.SHADOW_STEEL));source.fallDistance=10;LegacyItemData.of(source).putBoolean("JustCreated",true);source.tick();double first=source.getDeltaMovement().y;h.assertTrue(source.isNoGravity()&&source.isSilent()&&!LegacyItemData.of(source).contains("JustCreated")&&first>.2&&first<.27,"Real ItemEntity.tick executes source noGravity and fall-distance impulse before native movement");source.tick();h.assertTrue(source.getDeltaMovement().y<first,"Creation impulse does not replay on the next native tick");LegacyItemData.of(source).putBoolean("PlayEffects",true);var saved=save(source);saved.putShort("Age",(short)317);var decoded=load(h,saved);h.assertTrue(decoded.getAge()==317&&decoded.isNoGravity()&&decoded.isSilent()&&LegacyItemData.of(decoded).getBooleanOr("PlayEffects",false),"Actual native entity save/load retains age, physics and persisted once-only flags");h.succeed();}
 @GameTest public void legacyNeoForgeCreationFlagsMigrateThroughActualNativeLoad(GameTestHelper h){var source=source(h,1,0);source.setItem(new ItemStack(AllItems.REFINED_RADIANCE));var saved=save(source);saved.remove("CreateLegacy");var legacy=new CompoundTag();legacy.putBoolean("JustCreated",true);legacy.putBoolean("PlayEffects",true);saved.put("NeoForgeData",legacy);var decoded=load(h,saved);decoded.setDeltaMovement(.2,.1,.3);decoded.tick();h.assertTrue(decoded.isNoGravity()&&decoded.isSilent()&&decoded.getDeltaMovement().y>.3&&decoded.getDeltaMovement().y<.36&&!LegacyItemData.of(decoded).contains("JustCreated")&&LegacyItemData.of(decoded).getBooleanOr("PlayEffects",false),"Genuine native load migrates source flags and applies Radiance +.25 once");h.succeed();}
 @GameTest public void voidTransmutesEntireActualCompoundToPlainShadow(GameTestHelper h){var source=source(h,4,0);source.getItem().set(DataComponents.CUSTOM_NAME,Component.literal("Source intentionally consumes this name"));source.setPos(source.getX(),h.getLevel().getMinY()-12,source.getZ());source.tick();h.assertTrue(source.getItem().is(AllItems.SHADOW_STEEL)&&source.getItem().getCount()==4&&!source.getItem().has(DataComponents.CUSTOM_NAME)&&LegacyItemData.of(source).getBooleanOr("JustCreated",false),"Actual void branch uses plain Shadow construction for the whole paid actor");h.succeed();}
 @GameTest public void voidAndFullChargePreserveSourceFinalCompoundRemainder(GameTestHelper h){var source=source(h,2,10);source.getItem().set(DataComponents.CUSTOM_NAME,Component.literal("Only remainder keeps source metadata"));source.setPos(source.getX(),h.getLevel().getMinY()-12,source.getZ());source.tick();h.assertTrue(source.getItem().is(AllItems.CHROMATIC_COMPOUND)&&source.getItem().getCount()==1&&!source.getItem().has(AllDataComponents.CHROMATIC_COMPOUND_COLLECTING_LIGHT)&&source.getItem().has(DataComponents.CUSTOM_NAME),"Void temporary Shadow is actual paid stock; retired Compound is only source-intended remainder metadata");var radiance=h.getLevel().getEntitiesOfClass(ItemEntity.class,source.getBoundingBox().inflate(2),item->item.getItem().is(AllItems.REFINED_RADIANCE));h.assertTrue(radiance.size()==1&&radiance.getFirst().getItem().getCount()==1&&!radiance.getFirst().getItem().has(DataComponents.CUSTOM_NAME),"Exactly one plain Radiance; no stale second stock owner");h.succeed();}
 @GameTest public void rawBaselessBeaconBeamAllowsConversionThroughBedrockButStopsAtStone(GameTestHelper h){var p=h.absolutePos(SOURCE.below(3));h.getLevel().setBlockAndUpdate(p,Blocks.BEACON.defaultBlockState());var beacon=(BeaconBlockEntity)h.getLevel().getBlockEntity(p);try{var field=BeaconBlockEntity.class.getDeclaredField("beamSections");field.setAccessible(true);field.set(beacon,List.of(new BeaconBeamOwner.Section(0xffffff)));}catch(ReflectiveOperationException failure){throw new AssertionError(failure);}h.assertTrue(!((LegacyBeaconAccessor)beacon).create$legacyBeamSections().isEmpty()&&beacon.getBeamSections().isEmpty(),"Actual native raw beam state remains visible to source at zero beacon base level");h.getLevel().setBlockAndUpdate(p.above(),Blocks.STONE.defaultBlockState());var blocked=source(h,3,0);blocked.tick();h.assertTrue(blocked.getItem().is(AllItems.CHROMATIC_COMPOUND),"Source scan stops at opaque Stone despite stale raw beam state");blocked.discard();h.getLevel().setBlockAndUpdate(p.above(),Blocks.BEDROCK.defaultBlockState());var admitted=source(h,3,0);admitted.getItem().set(DataComponents.CUSTOM_NAME,Component.literal("Consumed by source plain conversion"));admitted.tick();h.assertTrue(admitted.getItem().is(AllItems.REFINED_RADIANCE)&&admitted.getItem().getCount()==3&&!admitted.getItem().has(DataComponents.CUSTOM_NAME),"Source's Bedrock exemption and actual native raw beam convert whole actor to plain Radiance");h.succeed();}
 @GameTest public void realConfigFileAndNativePacketKeepAuthoritativeServerSeparateFromClient(GameTestHelper h)throws Exception{var directory=Files.createTempDirectory("create-legacy-native-config-");var file=directory.resolve("recipes.json");try{var config=new CRecipes();config.reload(file);h.assertTrue(config.serverSettings().equals(CRecipes.Settings.DEFAULT)&&Files.isRegularFile(file),"Source defaults 10/true/true persist to a real config file");Files.writeString(file,"{\"lightSourceCountForRefinedRadiance\":23,\"enableRefinedRadianceRecipe\":false,\"enableShadowSteelRecipe\":true}");config.reload(file);var buffer=new RegistryFriendlyByteBuf(io.netty.buffer.Unpooled.buffer(),h.getLevel().registryAccess());try{LegacyConfigPacket.CODEC.encode(buffer,new LegacyConfigPacket(config.serverSettings()));var packet=LegacyConfigPacket.CODEC.decode(buffer);config.installClient(packet.settings());h.assertTrue(config.lightSourceCountForRefinedRadiance.get()==23&&!config.enableRefinedRadianceRecipe.get(),"Real network codec carries actual persisted source settings");config.installClient(new CRecipes.Settings(7,true,false));h.assertTrue(config.serverSettings().lightSourceCountForRefinedRadiance()==23&&config.effective().lightSourceCountForRefinedRadiance()==7,"Client sync cannot replace authoritative server recipe state");config.clearClient();h.assertTrue(config.effective().equals(config.serverSettings()),"Disconnect removes only client synced state");}finally{buffer.release();}}finally{Files.deleteIfExists(file);Files.deleteIfExists(directory);}h.succeed();}
}
